replace_once(path,"fireMeteorDrones=function multiplicityDrones(n,echoed=false){baseFireMeteorDrones(n,echoed);if(echoed)return;const extra=multishotStacks(),targets=nearestEnemies(player.x,player.y,extra,null,weaponRange('drone'));for(let i=0;i<extra;i++){const target=targets[i]||nearestWeaponTarget('drone');if(!target)continue;const a=i/Math.max(1,extra)*TAU+player.angle*.31,x=player.x+Math.cos(a)*(orbitRadiusFor('drone')+18),y=player.y+Math.sin(a)*(orbitRadiusFor('drone')+18),aim=Math.atan2(target.y-y,target.x-x);spawnPlayerProjectile({x,y,vx:Math.cos(aim)*530,vy:Math.sin(aim)*530,r:5.1,life:1.35,maxRange:weaponRange('drone'),damage:(9+n*2.6)*.72,color:'#baffea',pierce:n>=4?1:0,source:'drone-multiplicity',homingTargetId:target.id,homingReacquire:true,homingTurn:3.6});}};","fireMeteorDrones=function multiplicityDrones(n,echoed=false){const baseCount=n>=6?3:n>=2?2:1,baseTargets=nearestEnemies(player.x,player.y,baseCount,null,weaponRange('drone'));baseFireMeteorDrones(n,echoed);if(echoed)return;const extra=multishotStacks(),targets=multiplicityTargets(null,extra,'drone',baseTargets.map(target=>target.id));for(let i=0;i<extra;i++){const target=targets[i]||nearestWeaponTarget('drone');if(!target)continue;const a=i/Math.max(1,extra)*TAU+player.angle*.31,x=player.x+Math.cos(a)*(orbitRadiusFor('drone')+18),y=player.y+Math.sin(a)*(orbitRadiusFor('drone')+18),aim=Math.atan2(target.y-y,target.x-x);spawnPlayerProjectile({x,y,vx:Math.cos(aim)*530,vy:Math.sin(aim)*530,r:5.1,life:1.35,maxRange:weaponRange('drone'),damage:(9+n*2.6)*.72,color:'#baffea',pierce:n>=4?1:0,source:'drone-multiplicity',homingTargetId:target.id,homingReacquire:true,homingTurn:3.6,multiplicityTargetId:target.id});}};",'drone targets')
